```ts
import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

export function attachBigWorldFly(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  const fastKeys = [
    "KeyW",
    "KeyA",
    "KeyS",
    "KeyD",
    "ArrowUp",
    "ArrowDown",
    "ArrowLeft",
    "ArrowRight",
    "Space",
    "PageUp",
    "ShiftLeft",
    "ShiftRight",
    "PageDown",
  ];

  return attachConfigurableFreeControl(camera, canvas, scene, {
    fastKeys,
    fastMultiplier: 20,
  });
}
```

I attached the library's configurable free control with every default movement key listed as a "fast key" and a multiplier of 20, which makes each held key move the camera 20× as far per frame while leaving mouse look and the dispose path untouched. I'm confident in the mapping of the default keys (WASD, arrows, Space/PageUp up, Shift/PageDown down) from note 55, but I was not 100% certain that `fastMultiplier` scales the full per-frame displacement (including the inertia carry) rather than only the key-press increment—given the note that it "speeds things up" and that motion is velocity-based, I believe it does scale the whole thing, but I couldn't verify against the implementation.
